extension Binding where Value == Bool {
    func onChange(_ handler: @escaping (Bool) -> Void) -> Binding<Bool> {
        Binding(
            get: { self.wrappedValue },
            set: { newValue in
                self.wrappedValue = newValue
                handler(newValue)
            }
        )
    }
